(() => {
  const tg = window.Telegram?.WebApp; if(tg){tg.ready();tg.expand();}
  const $ = id => document.getElementById(id);
  const demoUserId = localStorage.getItem('gift_demo_user_id') || (()=>{const v='demo-'+Math.random().toString(16).slice(2);localStorage.setItem('gift_demo_user_id',v);return v;})();
  const startParam = new URLSearchParams(location.search).get('startapp') || '';
  const state = {settings:{},products:[],categories:[],services:[],cart:JSON.parse(localStorage.getItem('gift_cart')||'[]'),category:'ALL',customer:null,promo:null,customerLocation:null,quote:null,map:null,userMarker:null,businessMarker:null,liveWatchId:null,currentProduct:null,currentRating:0,currentReviews:[],detailSlideIndex:0,detailSlideTimer:null,detailTouchStartX:0};
  function headers(json=true){const h={}; if(json)h['Content-Type']='application/json'; if(tg?.initData)h['X-Telegram-Init-Data']=tg.initData; else h['X-Demo-User-Id']=demoUserId; return h;}
  async function api(url,opt={}){opt.headers={...headers(!(opt.body instanceof FormData)),...(opt.headers||{})}; if(opt.body instanceof FormData){delete opt.headers['Content-Type']; if(!tg?.initData)opt.body.append('demoUserId',demoUserId); if(startParam)opt.body.append('startParam',startParam);} const r=await fetch(url,opt); const d=await r.json().catch(()=>({success:false,message:'Server javobi noto‘g‘ri'})); if(!r.ok||d.success===false)throw new Error(d.message||'Xatolik'); return d;}
  function toast(msg,ms=3200){const t=$('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),ms)}
  function money(n){return `${Number(n||0).toLocaleString('uz-UZ')} ${state.settings.currency||'UZS'}`}
  function esc(s){return String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
  function saveCart(){localStorage.setItem('gift_cart',JSON.stringify(state.cart));renderCartBubble();}
  const CHECKOUT_DRAFT_KEY='gift_checkout_draft_v2';
  const DRAFT_FIELDS=['orderMode','deliveryDate','deliveryTime','eventType','recipientName','recipientPhone','cardMessage','planNote','productColors','productPackaging','productInscription','productReferenceLink','productAllergy','productExtraDetails','serviceRequesterName','serviceRequesterPhone','serviceRequesterAddress','serviceRecipientName','serviceRecipientPhone','serviceRecipientAddress','recipientRelation','recipientAge','serviceScenario','serviceSongName','servicePerformerPreference','serviceCallText','serviceMaterialsLink','serviceSpecialRequirements','orderType','deliveryService','orderAddress','promoCode','orderFullName','orderPhone','orderNote','paymentProvider'];
  const DRAFT_CHECKS=['productSubstitutionAllowed','serviceSecretMode','liveLocationEnabled','useBonus','noComplaintAgreement'];
  function saveCheckoutDraft(){try{const data={fields:{},checks:{},location:state.customerLocation,promo:state.promo,category:state.category,updatedAt:Date.now()};DRAFT_FIELDS.forEach(id=>{const el=$(id);if(el)data.fields[id]=el.value});DRAFT_CHECKS.forEach(id=>{const el=$(id);if(el)data.checks[id]=!!el.checked});localStorage.setItem(CHECKOUT_DRAFT_KEY,JSON.stringify(data));}catch{}}
  function restoreCheckoutDraft(){try{const raw=localStorage.getItem(CHECKOUT_DRAFT_KEY);if(!raw)return;const data=JSON.parse(raw);Object.entries(data.fields||{}).forEach(([id,v])=>{const el=$(id);if(el&&el.type!=='file')el.value=v});Object.entries(data.checks||{}).forEach(([id,v])=>{const el=$(id);if(el)el.checked=!!v});if(data.category){state.category=data.category;renderChips();renderProducts()}if(data.location?.lat&&data.location?.lng)setLocation(data.location.lat,data.location.lng,data.location.accuracy||0,data.location.source||'draft');if(data.promo)state.promo=data.promo;renderPaymentMethods();renderPaymentReturnNotice();renderCart();}catch{}}
  function bindDraftAutosave(){[...DRAFT_FIELDS,...DRAFT_CHECKS].forEach(id=>{const el=$(id);if(el)el.addEventListener(el.type==='checkbox'?'change':'input',()=>saveCheckoutDraft())});}
  function clearCheckoutDraft(){localStorage.removeItem(CHECKOUT_DRAFT_KEY);localStorage.removeItem('gift_payment_pending');localStorage.removeItem('gift_selected_payment');}
  function renderCartBubble(){const n=state.cart.reduce((a,b)=>a+b.qty,0);$('cartBubble').textContent=n;$('cartBubble').classList.toggle('hidden',!n)}
  window.showSection = function(id){document.querySelectorAll('.section').forEach(s=>s.classList.remove('active'));$(id)?.classList.add('active');document.querySelectorAll('.nav button').forEach(b=>b.classList.remove('active'));if($(`nav-${id}`))$(`nav-${id}`).classList.add('active');if(id==='cart'){renderCart();setTimeout(initMap,50)}if(id==='profile'){loadCustomer();loadOrders()}if(['catalog','express','servicesPage'].includes(id))renderProducts();}
  $('themeBtn').onclick=()=>{const dark=document.documentElement.getAttribute('data-theme')==='dark';document.documentElement.setAttribute('data-theme',dark?'light':'dark');localStorage.setItem('gift_theme',dark?'light':'dark')};document.documentElement.setAttribute('data-theme',localStorage.getItem('gift_theme')||'light');
  function productById(id){return state.products.find(p=>p._id===id)}
  function hasServiceCart(){return state.cart.some(i=>productById(i.productId)?.productType==='SERVICE')}
  function hasProductCart(){return state.cart.some(i=>{const p=productById(i.productId);return p&&p.productType!=='SERVICE'})}
  function renderCheckoutDetails(){const svc=hasServiceCart(), prod=hasProductCart();$('serviceDetailsBlock')?.classList.toggle('hidden',!svc);$('productDetailsBlock')?.classList.toggle('hidden',!prod);if(svc){if(!$('serviceRequesterName').value&&$('orderFullName').value)$('serviceRequesterName').value=$('orderFullName').value;if(!$('serviceRequesterPhone').value&&$('orderPhone').value)$('serviceRequesterPhone').value=$('orderPhone').value;if(!$('serviceRecipientName').value&&$('recipientName').value)$('serviceRecipientName').value=$('recipientName').value;if(!$('serviceRecipientPhone').value&&$('recipientPhone').value)$('serviceRecipientPhone').value=$('recipientPhone').value;if(!$('serviceRecipientAddress').value&&$('orderAddress').value)$('serviceRecipientAddress').value=$('orderAddress').value}}
  window.addToCart=function(id){const p=productById(id);if(!p)return;const x=state.cart.find(i=>i.productId===id);if(x)x.qty+=1;else state.cart.push({productId:id,qty:1});saveCart();toast(`${p.name} savatga qo‘shildi`);renderCart();}
  window.addAndCheckout=function(id,mode='SCHEDULED'){addToCart(id);if($('orderMode'))$('orderMode').value=mode;handleModeChange();showSection('cart');}
  window.prepareScheduledCheckout=function(){if($('orderMode'))$('orderMode').value='SCHEDULED';handleModeChange();showSection('cart');}
  window.prepareExpressCheckout=function(){if($('orderMode'))$('orderMode').value='EXPRESS_RANDOM';handleModeChange();showSection('cart');}
  window.prepareServiceCheckout=function(){showSection('servicesPage');}
  window.setQty=function(id,delta){const x=state.cart.find(i=>i.productId===id);if(!x)return;x.qty+=delta;if(x.qty<=0)state.cart=state.cart.filter(i=>i.productId!==id);saveCart();renderCart();}
  function subtotal(){return state.cart.reduce((sum,i)=>{const p=productById(i.productId);return sum+(p?Number(p.price)*i.qty:0)},0)}
  function firstDiscountEstimate(){return state.customer?.completedOrders===0 && state.settings.firstOrderDiscountEnabled!==false ? Math.min(subtotal(),Number(state.settings.firstOrderDiscountAmount||0)) : 0}
  function bonusUseEstimate(){if(!$('useBonus')?.checked||!state.customer||state.settings.bonusUseEnabled===false)return 0;const before=Math.max(0,subtotal()+(state.quote?.deliveryFee||0)-firstDiscountEstimate()-(state.promo?.amount||0));return Math.min(Number(state.customer.bonusBalance||0),before)}
  function categoryLabel(value){return String(value||'').toLowerCase()}
  function categoryIconSvg(value){
    const v=categoryLabel(value);
    const common='class="catIcon" viewBox="0 0 64 64" aria-hidden="true"';
    if(v.includes('gul')||v.includes('flower'))return `<svg ${common}><circle class="fill" cx="32" cy="31" r="23"/><path d="M32 40c8-7 14-13 14-21a8 8 0 0 0-14-5 8 8 0 0 0-14 5c0 8 6 14 14 21Z"/><path d="M32 40v15"/><path d="M22 48c8-2 10 2 10 2"/><path d="M42 47c-8-2-10 3-10 3"/></svg>`;
    if(v.includes('box')||v.includes('sovg'))return `<svg ${common}><rect class="fill" x="12" y="22" width="40" height="30" rx="5"/><path d="M12 22h40v30H12z"/><path d="M32 22v30"/><path d="M12 32h40"/><path d="M25 22c-7-4-8-12-2-12 5 0 7 7 9 12"/><path d="M39 22c7-4 8-12 2-12-5 0-7 7-9 12"/></svg>`;
    if(v.includes('tort')||v.includes('cake'))return `<svg ${common}><path class="fill" d="M14 29h36v22H14z"/><path d="M14 29h36v22H14z"/><path d="M18 29c3 6 7 0 10 0s7 6 10 0 7 6 12 0"/><path d="M24 20v9M32 18v11M40 20v9"/><path d="M24 15h0M32 13h0M40 15h0"/></svg>`;
    if(v.includes('shirin')||v.includes('sweet'))return `<svg ${common}><path class="fill" d="M22 22h20v20H22z"/><path d="M22 22h20v20H22z"/><path d="m22 32-12-8 6 16 6-8Z"/><path d="m42 32 12-8-6 16-6-8Z"/><path d="M28 27h8M28 37h8"/></svg>`;
    if(v.includes('ichim')||v.includes('drink'))return `<svg ${common}><path class="fill" d="M22 18h20l-4 36H26z"/><path d="M22 18h20l-4 36H26z"/><path d="M24 29h16"/><path d="M35 18l9-9"/><path d="M31 9h13"/></svg>`;
    if(v.includes('fast')||v.includes('food')||v.includes('burger'))return `<svg ${common}><path class="fill" d="M14 30h36v16H14z"/><path d="M14 31c2-10 34-10 36 0H14Z"/><path d="M14 42h36"/><path d="M16 49h32"/><path d="M23 25h0M32 23h0M41 25h0"/></svg>`;
    if(v.includes('xizmat')||v.includes('service'))return `<svg ${common}><circle class="fill" cx="32" cy="32" r="23"/><path d="M21 37c4-6 18-6 22 0"/><path d="M25 27a7 7 0 0 1 14 0"/><path d="M18 45h28"/><path d="M18 45c0-8 28-8 28 0"/><path d="M46 20l6-6"/><path d="M50 25h8"/></svg>`;
    return `<svg ${common}><circle class="fill" cx="32" cy="32" r="22"/><path d="M18 31h28v20H18z"/><path d="M32 31v20"/><path d="M18 39h28"/><path d="M25 31c-6-5-5-11 0-11 4 0 6 5 7 11"/><path d="M39 31c6-5 5-11 0-11-4 0-6 5-7 11"/></svg>`;
  }
  function chipMiniIcon(value){return categoryIconSvg(value).replace('class="catIcon"','class="chipSvg"')}
  function productImages(p){const arr=[];if(p.imageUrl)arr.push(p.imageUrl);if(Array.isArray(p.galleryUrls))arr.push(...p.galleryUrls);if(Array.isArray(p.images))arr.push(...p.images);if(Array.isArray(p.variants))arr.push(...p.variants.map(v=>v.imageUrl).filter(Boolean));return [...new Set(arr.filter(Boolean))].slice(0,8)}
  function productMedia(p){const imgs=productImages(p);if(imgs.length){return `<div class="pmedia" style="--n:${imgs.length}">${imgs.map((u,i)=>`<img class="pslide" style="--i:${i};--n:${imgs.length}" src="${esc(u)}" alt="${esc(p.name)}" loading="lazy">`).join('')}<div class="dots">${imgs.map(()=>'<i class="dot"></i>').join('')}</div></div>`}return `<div class="visualFallback">${categoryIconSvg(p.productType||p.category||p.emoji)}</div>`}
  function productMeta(p){const parts=[];if(p.shortDescription)parts.push(esc(p.shortDescription));if(p.packageIncludes)parts.push('Ichida: '+esc(p.packageIncludes));if((p.colorOptions||[]).length)parts.push('Rang: '+p.colorOptions.slice(0,3).map(esc).join(', '));if((p.flavorOptions||[]).length)parts.push('Ta’m: '+p.flavorOptions.slice(0,3).map(esc).join(', '));if(p.serviceDuration)parts.push('Davomiylik: '+esc(p.serviceDuration));if(p.serviceFormat)parts.push('Format: '+esc(p.serviceFormat));return parts.slice(0,2).map(x=>`<div class="muted">${x}</div>`).join('')}
  function matchesProductSearch(p,q){return !q||`${p.name} ${p.category} ${p.description} ${p.shortDescription||''} ${p.productType||''}`.toLowerCase().includes(q)}
  function isServiceProduct(p){return p.productType==='SERVICE'}
  function isExpressProduct(p){return p.expressTezkorAllowed||Number(p.minLeadDays||0)===0||String(p.name||'').toLowerCase().includes('random')}
  
function productCard(p,mode='scheduled'){
    const cls=isServiceProduct(p)?'serviceProduct':isExpressProduct(p)?'fastProduct':'';
    const badge=mode==='express'?'1 soat':isServiceProduct(p)?'Xizmat':p.featured?'Tavsiya':'';
    const actionMode=mode==='express'?'EXPRESS_RANDOM':'SCHEDULED';
    const variantPrices=((p.variants||[]).map(v=>Number(v.price||0)).filter(Boolean));
    const from=variantPrices.length?Math.min(Number(p.price||0)||variantPrices[0], ...variantPrices):Number(p.price||0);
    const rate=p.avgRating&&Number(p.reviewCount||0)?`<div class="muted">Baho: ${esc(p.avgRating)} / 5 · ${Number(p.reviewCount||0)} ta fikr</div>`:'';
    return `<div class="card product ${cls}" onclick="openProduct('${p._id}')"><div class="pimg">${productMedia(p)}${badge?`<span class="badge">${badge}</span>`:''}${p.promoCode?'<span class="badge right">Aksiya</span>':''}</div><div class="pbody"><h3>${esc(p.name)}</h3><p class="desc">${esc(p.shortDescription||p.description||'')}</p>${productMeta(p)}${rate}<div class="variantLine">${(p.variants||[]).length?`Variantlar: ${(p.variants||[]).length} ta`:esc(p.category)+' · '+(isExpressProduct(p)?'tezkor':(p.minLeadDays||0)+' kun oldin')}</div>${p.promoCode?`<div class="pill">${esc(p.promoCode)} -${p.promoDiscountPercent||0}%</div>`:''}<div class="priceRow"><div><div class="price">${money(from)}</div>${p.oldPrice?`<div class="old">${money(p.oldPrice)}</div>`:''}</div><button class="add" onclick="event.stopPropagation();openProduct('${p._id}')">Ko‘rish</button></div></div></div>`}
  window.renderProducts=function(){
    const q=($('search')?.value||'').toLowerCase();
    const catalog=state.products.filter(p=>!isServiceProduct(p)&&(state.category==='ALL'||p.category===state.category)&&matchesProductSearch(p,q));
    if($('productGrid'))$('productGrid').innerHTML=catalog.length?catalog.map(p=>productCard(p,'scheduled')).join(''):'<div class="empty" style="grid-column:1/-1">Oldindan buyurtma mahsuloti topilmadi.</div>';
    const qe=($('searchExpress')?.value||'').toLowerCase();
    const express=state.products.filter(p=>!isServiceProduct(p)&&isExpressProduct(p)&&matchesProductSearch(p,qe));
    if($('expressGrid'))$('expressGrid').innerHTML=express.length?express.map(p=>productCard(p,'express')).join(''):'<div class="empty" style="grid-column:1/-1">Tezkor mahsulot yo‘q. Boshqaruv panelidan “Tezkor” ruxsatini yoqing.</div>';
    const qs=($('searchServices')?.value||'').toLowerCase();
    const services=state.products.filter(p=>isServiceProduct(p)&&matchesProductSearch(p,qs));
    if($('servicesGrid'))$('servicesGrid').innerHTML=services.length?services.map(p=>productCard(p,'service')).join(''):'<div class="empty" style="grid-column:1/-1">Xizmatlar hozircha qo‘shilmagan.</div>';
  }
  function renderChips(){const cats=(state.categories||[]).filter(c=>!String(c).toLowerCase().includes('xizmat'));$('chips').innerHTML=['ALL',...cats].map(c=>`<button class="chip ${state.category===c?'active':''}" onclick="selectCategory('${esc(c)}')">${c==='ALL'?'':chipMiniIcon(c)}<span>${c==='ALL'?'Hammasi':esc(c)}</span></button>`).join('')}
  window.selectCategory=function(c){state.category=c;renderChips();renderProducts();}
  function renderServices(){const list=state.services||[];if($('deliveryService'))$('deliveryService').innerHTML=list.map(s=>`<option value="${s._id}">${esc(s.title)} · ${money(s.price)}</option>`).join('')}
  const DEFAULT_PAYMENT_LINKS={PAYNET:"https://app.paynet.uz/qr-online/00020101021140440012qr-online.uz01186r0vBrkobM1uBpXqv40202115204531153038605802UZ5910AO'PAYNET'6008Tashkent610610002164280002uz0106PAYNET0208Toshkent80520012qr-online.uz03097120207070419marketing@paynet.uz63042E24",CLICK:'https://my.click.uz/clickp2p/64FF6DA1B8F00B46B2936F561CCF73B01A05A23D2130A2B7F7A9E217A12F0BBD',UZUM:'https://b.2u.uz/ttc?qr=Nzk5MzoyMDQzNTUwMzowMUtTUE1XM0gwSE03RTFUNzRDTU5XRkZLNzpkMUhZYmhKWDZ3UGVQYVkxcW9mU3pVTmRHcVU9',XAZNA:'https://pay.xazna.uz/p2p/e07e655f-886e-4942-b325-846d8a0c2ce9'};
  function paymentProviders(){const s=state.settings||{};return [{id:'PAYNET',title:'Paynet',hint:'QR to‘lov',icon:'P',url:s.paymentPaynetUrl||DEFAULT_PAYMENT_LINKS.PAYNET},{id:'CLICK',title:'Click',hint:'Click orqali',icon:'C',url:s.paymentClickUrl||DEFAULT_PAYMENT_LINKS.CLICK},{id:'UZUM',title:'Uzum Bank',hint:'Bank ilovasi',icon:'U',url:s.paymentUzumUrl||DEFAULT_PAYMENT_LINKS.UZUM},{id:'XAZNA',title:'Xazna',hint:'P2P to‘lov',icon:'X',url:s.paymentXaznaUrl||DEFAULT_PAYMENT_LINKS.XAZNA}].filter(x=>x.url)}
  function selectedPayment(){return $('paymentProvider')?.value||localStorage.getItem('gift_selected_payment')||''}
  function renderPaymentMethods(){const list=paymentProviders();const selected=selectedPayment()||list[0]?.id||'';if($('paymentProvider'))$('paymentProvider').value=selected;if(selected)localStorage.setItem('gift_selected_payment',selected);$('paymentMethods').innerHTML=list.map(p=>`<button type="button" class="payMethod ${selected===p.id?'active':''}" onclick="choosePaymentProvider('${p.id}')"><span class="payIcon">${p.icon}</span><span><b>${p.title}</b><small>${p.hint}</small></span></button>`).join('')||'<div class="muted">To‘lov linklari sozlanmagan.</div>';updatePaymentInfo()}
  window.choosePaymentProvider=id=>{if(!$('paymentProvider'))return;$('paymentProvider').value=id;localStorage.setItem('gift_selected_payment',id);renderPaymentMethods();saveCheckoutDraft();}
  function paymentProviderById(id){return paymentProviders().find(p=>p.id===id)}
  window.renderCart=function(){const list=state.cart.map(i=>{const p=productById(i.productId);return p?`<div class="cartItem"><div><b>${esc(p.name)}</b><div class="muted">${money(p.price)} × ${i.qty} = ${money(p.price*i.qty)}</div></div><div class="qty"><button onclick="setQty('${p._id}',-1)">−</button><b>${i.qty}</b><button onclick="setQty('${p._id}',1)">+</button></div></div>`:''}).join('');$('cartList').innerHTML=list||'<div class="empty">Savat bo‘sh. Katalogdan mahsulot tanlang.</div>';const delivery=state.quote?.deliveryFee||0;const first=firstDiscountEstimate();const promo=state.promo?.amount||0;const bonus=bonusUseEstimate();const total=Math.max(0,subtotal()+delivery-first-promo-bonus);$('summary').innerHTML=`<div class="srow"><span>Mahsulotlar</span><b>${money(subtotal())}</b></div><div class="srow"><span>Yetkazish</span><b>${money(delivery)}</b></div>${first?`<div class="srow"><span>Birinchi xarid chegirmasi</span><b class="ok">−${money(first)}</b></div>`:''}${promo?`<div class="srow"><span>Aksiya kodi ${esc(state.promo.code)}</span><b class="ok">−${money(promo)}</b></div>`:''}${bonus?`<div class="srow"><span>Bonusdan foydalanish</span><b class="ok">−${money(bonus)}</b></div>`:''}<div class="srow total"><span>Jami</span><b>${money(total)}</b></div><div class="muted">Tizim yakuniy summani aksiya kodi, bonus va km narx bo‘yicha qayta tekshiradi.</div>`;$('bonusUseText').textContent=`Bonusdan foydalanish (${money(state.customer?.bonusBalance||0)} mavjud)`;renderCartBubble();renderCheckoutDetails();updatePaymentInfo();}
  window.handleModeChange=function(){const mode=$('orderMode').value;const s=state.settings;$('scheduledInfo').classList.toggle('hidden',mode!=='SCHEDULED');$('expressInfo').classList.toggle('hidden',mode!=='EXPRESS_RANDOM');if(mode==='SCHEDULED'){$('deliveryDate').max='';$('deliveryDate').min=addDays(Number(s.scheduledMinLeadDays||4));if(!$('deliveryDate').value||$('deliveryDate').value<$('deliveryDate').min)$('deliveryDate').value=$('deliveryDate').min}else{$('deliveryDate').min=addDays(0);$('deliveryDate').max=addDays(0);$('deliveryDate').value=addDays(0);$('deliveryTime').value=timePlusHours(Math.max(1,Number(s.expressMaxLeadHours||1)));}renderCart()}
  function addDays(n){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)}
  function timePlusHours(h=1){const d=new Date(Date.now()+Math.max(1,Number(h||1))*3600000);return `${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`}
  window.handleTypeChange=function(){const isDelivery=$('orderType').value==='DELIVERY';$('deliveryBlock').classList.toggle('hidden',!isDelivery);quoteDelivery();handlePaymentChange();}
  window.handlePaymentChange=function(){if($('paymentMethod'))$('paymentMethod').value='CARD_TRANSFER';$('chek rasmiField')?.classList.remove('hidden');renderPaymentMethods();}
  function currentTotal(){const delivery=state.quote?.deliveryFee||0;const first=firstDiscountEstimate();const promo=state.promo?.amount||0;const bonus=bonusUseEstimate();return Math.max(0,subtotal()+delivery-first-promo-bonus)}
  function renderPaymentReturnNotice(){const box=$('paymentReturnNotice');if(!box)return;try{const pending=JSON.parse(localStorage.getItem('gift_payment_pending')||'null');if(pending?.provider){box.classList.remove('hidden');box.innerHTML=`${esc(pending.title||pending.provider)} ochilgan. Mini appga qaytgan bo‘lsangiz, chek rasmini tanlab buyurtmani yuboring. Summa: <b>${money(pending.total||currentTotal())}</b>`;}else box.classList.add('hidden');}catch{box.classList.add('hidden')}}
  function updatePaymentInfo(){const p=paymentProviderById(selectedPayment());$('cardTitle').textContent=p?`${p.title} orqali oldindan to‘lov`:'To‘lov';$('cardNumber').textContent=p?'To‘lov ilovasiga o‘tish':'Ilovani tanlang';$('cardHolder').textContent=`Jami: ${money(currentTotal())}. To‘lovdan keyin qaytib chek rasmini yuklang.`;renderPaymentReturnNotice();}
  window.openSelectedPayment=()=>{const p=paymentProviderById(selectedPayment());const amount=Math.round(currentTotal());if(!state.cart.length)return toast('Savat bo‘sh');if(!p)return toast('To‘lov ilovasini tanlang');saveCheckoutDraft();localStorage.setItem('gift_payment_pending',JSON.stringify({provider:p.id,title:p.title,total:amount,openedAt:Date.now()}));renderPaymentReturnNotice();toast(`${p.title} ochilmoqda. Qaytgach chek rasmini yuklang.`,4500);setTimeout(()=>{if(tg?.openLink)tg.openLink(p.url,{try_instant_view:false});else window.open(p.url,'_blank');},350)}

  function initMap(){if(!window.L||state.map)return;const s=state.settings;const lat=Number(s.businessLat||s.restaurantLat||38.86),lng=Number(s.businessLng||s.restaurantLng||65.58);state.map=L.map('map',{zoomControl:true}).setView([lat,lng],13);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(state.map);state.businessMarker=L.marker([lat,lng],{title:'Biznes'}).addTo(state.map).bindPopup('Biznes joylashuvi');state.map.on('click',e=>setLocation(e.latlng.lat,e.latlng.lng,0,'map_click'));setTimeout(()=>state.map.invalidateSize(),200)}
  function setLocation(lat,lng,accuracy=0,source='client'){state.customerLocation={lat,lng,accuracy,source};if(!state.map)initMap();if(state.userMarker)state.userMarker.setLatLng([lat,lng]);else state.userMarker=L.marker([lat,lng],{draggable:true,title:'Mijoz'}).addTo(state.map);state.userMarker.on('dragend',e=>{const p=e.target.getLatLng();setLocation(p.lat,p.lng,0,'dragged')});state.map.setView([lat,lng],15);quoteDelivery();}
  window.focusBusiness=function(){const s=state.settings;if(state.map)state.map.setView([Number(s.businessLat||s.restaurantLat),Number(s.businessLng||s.restaurantLng)],15)}
  window.locateMe=function(){if(!navigator.geolocation)return toast('GPS qo‘llab-quvvatlanmaydi');toast('GPS aniqlanmoqda...');let best=null,done=0;for(let i=0;i<3;i++){navigator.geolocation.getCurrentPosition(pos=>{done++;if(!best||pos.coords.accuracy<best.coords.accuracy)best=pos;if(done===3){setLocation(best.coords.latitude,best.coords.longitude,best.coords.accuracy,'gps');toast(best.coords.accuracy>1500?'GPS taxminiy. Pinni qo‘lda suring.':'Lokatsiya belgilandi')}},()=>{done++;if(done===3&&!best)toast('GPS olinmadi. Xaritadan pin qo‘ying.')},{enableHighAccuracy:true,maximumAge:0,timeout:18000})}}
  window.searchAddress=async()=>{const q=$('geoSearch').value.trim();if(!q)return toast('Manzil yozing');try{const r=await fetch(`https://nominatim.openstreetmap.org/search?format=json&limit=1&q=${encodeURIComponent(q)}`);const d=await r.json();if(!d[0])return toast('Manzil topilmadi');setLocation(Number(d[0].lat),Number(d[0].lon),0,'search');toast('Qidiruvdan lokatsiya qo‘yildi')}catch{toast('Qidiruv xatosi')}}
  window.quoteDelivery=async()=>{try{if($('orderType')?.value==='PICKUP'){state.quote={deliveryFee:0,distanceKm:0,zoneStatus:'PICKUP'};renderLocationInfo();renderCart();return}const body={type:$('orderType')?.value||'DELIVERY',deliveryServiceId:$('deliveryService')?.value||''};if(state.customerLocation)Object.assign(body,{lat:state.customerLocation.lat,lng:state.customerLocation.lng,accuracy:state.customerLocation.accuracy,source:state.customerLocation.source});const d=await api('/api/delivery/quote',{method:'POST',body:JSON.stringify(body)});state.quote=d.quote;renderLocationInfo();renderCart()}catch(e){toast(e.message)}}
  function renderLocationInfo(){const loc=state.customerLocation,q=state.quote;if(!loc){$('locationInfo').innerHTML='<div class="qchip"><span>Lokatsiya</span><b>Belgilanmagan</b></div>';return}const mapUrl=`https://www.google.com/maps?q=${loc.lat},${loc.lng}`;$('locationInfo').innerHTML=`<div class="qchip"><span>Masofa</span><b>${q?.distanceKm||0} km</b></div><div class="qchip"><span>Yetkazish narxi</span><b>${money(q?.deliveryFee||0)}</b></div><div class="qchip"><span>Hudud</span><b>${q?.zoneStatus==='OUT_OF_ZONE'?'Hududdan tashqari':'Hudud ichida'}</b></div><a class="ghost mini" target="_blank" href="${mapUrl}">Xaritada ochish</a>`}
  window.applyPromo=async()=>{try{if(!subtotal())return toast('Savat bo‘sh');const body={items:state.cart,promoCode:$('promoCode').value,type:$('orderType').value};if(state.customerLocation)Object.assign(body,{lat:state.customerLocation.lat,lng:state.customerLocation.lng,accuracy:state.customerLocation.accuracy,source:state.customerLocation.source});const d=await api('/api/promo/validate',{method:'POST',body:JSON.stringify(body)});state.promo=d.promo;toast(`Aksiya kodi qo‘llandi: −${money(d.promo.amount)}`);renderCart()}catch(e){state.promo=null;renderCart();toast(e.message)}}
  function startLiveTracking(orderId){if(!orderId||!navigator.geolocation)return;localStorage.setItem('gift_live_order_id',orderId);if(state.liveWatchId)navigator.geolocation.clearWatch(state.liveWatchId);state.liveWatchId=navigator.geolocation.watchPosition(async pos=>{try{if(Number(pos.coords.accuracy||0)>1500)return;await api(`/api/orders/${orderId}/location`,{method:'POST',body:JSON.stringify({lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy:pos.coords.accuracy||0,source:'live'})})}catch{}},()=>{}, {enableHighAccuracy:true,maximumAge:0,timeout:20000})}
  window.stopLive=()=>{if(state.liveWatchId)navigator.geolocation.clearWatch(state.liveWatchId);state.liveWatchId=null;localStorage.removeItem('gift_live_order_id');toast('Jonli lokatsiya to‘xtadi')}
  window.resumeLive=(id)=>startLiveTracking(id);
  window.submitOrder=async()=>{try{if(!state.cart.length)throw new Error('Savat bo‘sh');const svc=hasServiceCart(), prod=hasProductCart();if(!$('orderPhone').value.trim())throw new Error('Telefon kiriting');if(!$('deliveryDate').value||!$('deliveryTime').value)throw new Error('Yetkazish kuni va vaqtini tanlang');if($('orderType').value==='DELIVERY'&&!state.customerLocation)throw new Error('Yetkazish uchun lokatsiya belgilang');if($('orderType').value==='DELIVERY'&&!$('orderAddress').value.trim())throw new Error('Manzil/mo‘ljal kiriting');if($('orderMode').value==='EXPRESS_RANDOM'&&!$('noComplaintAgreement').checked)throw new Error('Tezkor buyurtma roziligini belgilang');if(svc){if(!$('serviceRequesterName').value.trim())throw new Error('Xizmat uchun buyurtma beruvchi ism-familiyasini kiriting');if(!$('serviceRequesterPhone').value.trim())throw new Error('Xizmat uchun buyurtma beruvchi telefonini kiriting');if(!$('serviceRecipientName').value.trim())throw new Error('Xizmat qabul qiluvchi ism-familiyasini kiriting');if(!$('serviceRecipientPhone').value.trim())throw new Error('Xizmat qabul qiluvchi telefonini kiriting');if(!$('serviceRecipientAddress').value.trim()&&$('orderType').value==='DELIVERY')throw new Error('Xizmat qabul qiluvchi manzilini kiriting')}if(!$('paymentProvider').value)throw new Error('To‘lov ilovasini tanlang');if(!$('screenshot').files[0])throw new Error('Oldindan to‘lov cheki rasmini yuklang');saveCheckoutDraft();const fd=new FormData();['orderMode','deliveryDate','deliveryTime','eventType','recipientName','recipientPhone','cardMessage','planNote'].forEach(id=>fd.append(id,$(id).value));['productColors','productPackaging','productInscription','productReferenceLink','productAllergy','productExtraDetails'].forEach(id=>fd.append(id,$(id)?.value||''));fd.append('productTheme',$('eventType').value);fd.append('productSubstitutionAllowed',$('productSubstitutionAllowed')?.checked?'true':'false');['serviceRequesterName','serviceRequesterPhone','serviceRequesterAddress','serviceRecipientName','serviceRecipientPhone','serviceRecipientAddress','recipientRelation','recipientAge','serviceScenario','serviceSongName','servicePerformerPreference','serviceCallText','serviceMaterialsLink','serviceSpecialRequirements'].forEach(id=>fd.append(id,$(id)?.value||''));fd.append('serviceSecretMode',$('serviceSecretMode')?.checked?'true':'false');fd.append('items',JSON.stringify(state.cart));fd.append('type',$('orderType').value);fd.append('deliveryServiceId',$('deliveryService').value);fd.append('phone',$('orderPhone').value);fd.append('fullName',$('orderFullName').value);fd.append('address',$('orderAddress').value);fd.append('note',$('orderNote').value);fd.append('paymentMethod','CARD_TRANSFER');fd.append('paymentProvider',$('paymentProvider').value);fd.append('promoCode',$('promoCode').value);fd.append('useBonus',$('useBonus').checked?'true':'false');fd.append('noComplaintAgreement',$('noComplaintAgreement').checked?'true':'false');fd.append('liveLocationEnabled',$('liveLocationEnabled').checked?'true':'false');if(startParam)fd.append('referralCode',startParam);if(state.customerLocation){fd.append('customerLat',state.customerLocation.lat);fd.append('customerLng',state.customerLocation.lng);fd.append('customerAccuracy',state.customerLocation.accuracy||0);fd.append('locationSource',state.customerLocation.source||'client');fd.append('serviceRecipientLat',state.customerLocation.lat);fd.append('serviceRecipientLng',state.customerLocation.lng);fd.append('serviceRecipientAccuracy',state.customerLocation.accuracy||0);fd.append('serviceRecipientSource','map_pin')}if($('screenshot').files[0])fd.append('screenshot',$('screenshot').files[0]);const d=await api('/api/orders',{method:'POST',body:fd});state.cart=[];state.promo=null;clearCheckoutDraft();saveCart();toast(`Buyurtma yuborildi: #${d.order.orderNo}`);if($('liveLocationEnabled').checked&&$('orderType').value==='DELIVERY')startLiveTracking(d.order._id);showSection('orders');await loadOrders();await loadCustomer()}catch(e){toast(e.message,5000)}}
  function statusText(o){return {NEW:'Qabul qilindi',CONFIRMED:'Tasdiqlandi',PREPARING:'Tayyorlanmoqda',SHOPPING:'Xarid qilinmoqda',ON_ROAD:'Yo‘lda',READY:'Tayyor',DONE:'Yetkazildi',CANCELLED:'Bekor qilindi'}[o.orderStatus]||o.orderStatus}
  function payStatusText(v){return {PENDING:'Kutilmoqda',APPROVED:'Tasdiqlandi',REJECTED:'Rad etildi'}[v]||v||''}
  function moveText(v){return {UNKNOWN:'Nomaʼlum',APPROACHING:'Yaqinlashmoqda',MOVING_AWAY:'Uzoqlashmoqda',STABLE:'Barqaror'}[v]||v||''}
  window.loadOrders=async()=>{try{const d=await api('/api/my/orders');$('ordersList').innerHTML=d.orders.length?d.orders.map(o=>{const active=o.type==='DELIVERY'&&!['DONE','CANCELLED'].includes(o.orderStatus);return `<div class="statusCard"><b>#${esc(o.orderNo)} · ${money(o.total)}</b><div class="muted">${new Date(o.createdAt).toLocaleString('uz-UZ')} · ${o.deliveryDate||''} ${o.deliveryTime||''}</div><div>${o.items.map(i=>`<span class="pill">${esc(i.name)} × ${i.qty}</span>`).join('')}</div><div><span class="pill">${o.orderMode==='EXPRESS_RANDOM'?'Tezkor':'Oldindan'}</span><span class="pill ${o.paymentStatus==='APPROVED'?'ok':o.paymentStatus==='REJECTED'?'bad':'warn'}">To‘lov: ${payStatusText(o.paymentStatus)}</span><span class="pill ${o.orderStatus==='DONE'?'ok':o.orderStatus==='CANCELLED'?'bad':''}">${statusText(o)}</span></div><div class="muted">Yetkazish: ${money(o.deliveryFee)} · Chegirma: ${money(o.discountAmount)} · Bonus: +${money(o.bonusEarned)}</div>${o.distanceKm?`<div class="muted">${o.distanceKm} km · ${moveText(o.movementTrend)}</div>`:''}${active?`<div class="shareBox"><button class="ghost mini" onclick="resumeLive('${o._id}')">Jonli lokatsiya</button><button class="ghost mini" onclick="stopLive()">To‘xtatish</button></div>`:''}</div>`}).join(''):'<div class="empty">Hozircha buyurtma yo‘q.</div>'}catch(e){$('ordersList').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
  window.loadCustomer=async()=>{try{const d=await api(`/api/customer/me${startParam?`?startParam=${encodeURIComponent(startParam)}`:''}`);state.customer=d.customer;const balance=money(d.customer.bonusBalance||0);const completed=Number(d.customer.completedOrders||0);const percent=Number(state.settings.cashbackPercent||0);$('profileBox').innerHTML=`<div class="bonusCard"><div class="profileHead"><div><div class="bonusCode">Taklif kodi: <b>${esc(d.customer.referralCode)}</b></div><h3>GiftGo Bonus karta</h3><div class="bonusBig">${balance}</div><div class="bonusSub">Premium gul va sovg‘a buyurtmalarida bonus, cashback va referral bir joyda.</div></div><span class="supportIcon">${infoIconSvg('gift')}</span></div><div class="bonusStatGrid"><div class="bonusStat"><b>${completed}</b><span>Yakunlangan</span></div><div class="bonusStat"><b>${percent}%</b><span>Cashback</span></div><div class="bonusStat"><b>${money(state.settings.referralInviterBonusAmount||0)}</b><span>Taklif bonusi</span></div></div><div class="profileShare"><button class="btn" onclick="shareReferral('${encodeURIComponent(d.shareUrl)}','${encodeURIComponent(d.shareText)}')">Telegramga ulashish</button><button class="ghost" onclick="copyReferral('${esc(d.shareUrl)}')">Havolani nusxalash</button></div><div class="profileInfoNote">Har yakunlangan buyurtmada ${percent}% keshbek hisoblanadi. Taklif havolasi orqali kelgan do‘st birinchi xarid qilsa sizga bonus tushadi.</div></div>`;$('bonusUseText').textContent=`Bonusdan foydalanish (${money(d.customer.bonusBalance||0)} mavjud)`;renderCart()}catch(e){$('profileBox').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
window.shareReferral=(url,text)=>{const link=`https://t.me/share/url?url=${url}&text=${text}`;if(tg?.openTelegramLink)tg.openTelegramLink(link);else location.href=link}
  window.copyReferral=async(url)=>{try{await navigator.clipboard.writeText(url);toast('Taklif havolasi nusxalandi')}catch{toast('Nusxalab bo‘lmadi')}}
  function renderSupportLinks(){const s=state.settings||{};const phone=String(s.supportPhone||s.businessPhone||s.restaurantPhone||'+998887660800').replace(/\s+/g,'');const tgUser=String(s.supportTelegram||'@Qoryogdiyev').trim().replace(/^@/,'');const box=$('supportLinks');if(box)box.innerHTML=`<div class="supportGrid"><div class="supportCard"><span class="supportIcon"><svg viewBox="0 0 24 24"><path d="M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7l.4 2.6a2 2 0 0 1-.6 1.8L7.2 9.8a16 16 0 0 0 7 7l1.7-1.7a2 2 0 0 1 1.8-.6l2.6.4A2 2 0 0 1 22 16.9Z"/></svg></span><b>Qo‘ng‘iroq qilish</b><div class="muted">Tezkor savollar va buyurtma bo‘yicha yordam</div><div class="profileShare" style="margin-top:8px;grid-template-columns:1fr"><a class="btn" href="tel:${phone}">${esc(phone)}</a></div></div><div class="supportCard"><span class="supportIcon"><svg viewBox="0 0 24 24"><path d="M21 4 3 11l7 2 2 7 9-16Z"/><path d="M10 13 21 4"/></svg></span><b>Telegram chat</b><div class="muted">Admin bilan yozishma va tezkor aloqa</div><div class="profileShare" style="margin-top:8px;grid-template-columns:1fr"><a class="ghost" target="_blank" href="https://t.me/${tgUser}">@${esc(tgUser)}</a></div></div></div>`;}
async function boot(){try{const b=await api('/api/bootstrap');state.settings=b.settings;state.products=b.products;state.categories=b.categories;state.services=b.services;$('brandName').textContent=b.settings.brandName;$('brandSub').textContent=b.settings.brandSubtitle;$('logo').src=b.settings.logoUrl;$('agreementText').textContent=b.settings.expressAgreementText;cleanBusinessText();renderChips();renderProducts();renderServices();renderSupportLinks();bindDraftAutosave();handleModeChange();handlePaymentChange();restoreCheckoutDraft();renderCart();await loadCustomer();const name=tg?.initDataUnsafe?.user?[tg.initDataUnsafe.user.first_name,tg.initDataUnsafe.user.last_name].filter(Boolean).join(' '):'';if(!$('orderFullName').value)$('orderFullName').value=name;saveCheckoutDraft();}catch(e){toast(e.message,6000)}}

function findVariant(product, sku, label){const vs=Array.isArray(product?.variants)?product.variants:[];return vs.find(v=>sku?String(v.sku||'')===String(sku):String(v.label||'')===String(label));}
function unitPrice(item){const p=productById(item.productId);if(!p)return 0;const v=findVariant(p,item.variantSku,item.variantLabel);return Number(v?.price||item.price||p.price||0)}
function cartKey(item){return `${item.productId}__${item.variantSku||item.variantLabel||''}`}
window.addToCart=function(id,opts={}){const p=productById(id);if(!p)return;const item={productId:id,qty:1,variantSku:opts.variantSku||'',variantLabel:opts.variantLabel||'',selectedColor:opts.selectedColor||'',selectedSize:opts.selectedSize||'',price:opts.price||p.price};const key=cartKey(item);const x=state.cart.find(i=>cartKey(i)===key);if(x)x.qty+=1;else state.cart.push(item);saveCart();toast(`${p.name} savatga qo‘shildi`);renderCart();}
window.addAndCheckout=function(id,mode='SCHEDULED'){addToCart(id);if($('orderMode'))$('orderMode').value=mode;handleModeChange();showSection('cart');}
window.setQty=function(keyOrId,delta){const idx=state.cart.findIndex(i=>cartKey(i)===keyOrId||i.productId===keyOrId);if(idx<0)return;state.cart[idx].qty+=delta;if(state.cart[idx].qty<=0)state.cart.splice(idx,1);saveCart();renderCart();}
function subtotal(){return state.cart.reduce((s,i)=>s+unitPrice(i)*i.qty,0)}
window.renderCart=function(){const list=state.cart.map(i=>{const p=productById(i.productId);const price=unitPrice(i);return p?`<div class="cartItem"><div><b>${esc(p.name)}</b>${i.variantLabel?`<div class="muted">Variant: ${esc(i.variantLabel)}</div>`:''}<div class="muted">${money(price)} × ${i.qty} = ${money(price*i.qty)}</div></div><div class="qty"><button onclick="setQty('${cartKey(i)}',-1)">−</button><b>${i.qty}</b><button onclick="setQty('${cartKey(i)}',1)">+</button></div></div>`:''}).join('');$('cartList').innerHTML=list||'<div class="empty">Savat bo‘sh. Katalogdan mahsulot tanlang.</div>';const delivery=state.quote?.deliveryFee||0;const first=firstDiscountEstimate();const promo=state.promo?.amount||0;const bonus=bonusUseEstimate();const total=Math.max(0,subtotal()+delivery-first-promo-bonus);$('summary').innerHTML=`<div class="srow"><span>Mahsulotlar</span><b>${money(subtotal())}</b></div><div class="srow"><span>Yetkazish</span><b>${money(delivery)}</b></div>${first?`<div class="srow"><span>Birinchi xarid chegirmasi</span><b class="ok">−${money(first)}</b></div>`:''}${promo?`<div class="srow"><span>Aksiya kodi ${esc(state.promo.code)}</span><b class="ok">−${money(promo)}</b></div>`:''}${bonus?`<div class="srow"><span>Bonusdan foydalanish</span><b class="ok">−${money(bonus)}</b></div>`:''}<div class="srow total"><span>Jami</span><b>${money(total)}</b></div><div class="muted">Tizim yakuniy summani aksiya kodi, bonus va km narx bo‘yicha qayta tekshiradi.</div>`;$('bonusUseText').textContent=`Bonusdan foydalanish (${money(state.customer?.bonusBalance||0)} mavjud)`;renderCartBubble();renderCheckoutDetails();updatePaymentInfo();}
async function loadReviewSummary(){await Promise.all(state.products.map(async p=>{try{const d=await api(`/api/products/${p._id}/reviews`);p.avgRating=d.avgRating;p.reviewCount=d.reviewCount;}catch{p.avgRating='0.0';p.reviewCount=0;}}));}
function infoIconSvg(type='gift'){const icons={gift:`<svg class="infoIcon" viewBox="0 0 24 24"><path d="M20 12v8H4v-8"/><path d="M2 7h20v5H2z"/><path d="M12 7v13"/><path d="M7 7c-3-2-2-5 .5-5C10 2 11 5 12 7"/><path d="M17 7c3-2 2-5-.5-5C14 2 13 5 12 7"/></svg>`,spark:`<svg class="infoIcon" viewBox="0 0 24 24"><path d="M12 3l2.6 5.3L20 11l-5.4 2.7L12 21l-2.6-7.3L4 11l5.4-2.7Z"/></svg>`,truck:`<svg class="infoIcon" viewBox="0 0 24 24"><path d="M3 7h11v10H3z"/><path d="M14 11h4l3 3v3h-7z"/><circle cx="7" cy="19" r="2"/><circle cx="18" cy="19" r="2"/></svg>`,care:`<svg class="infoIcon" viewBox="0 0 24 24"><path d="M12 21s8-5 8-12a5 5 0 0 0-8-4 5 5 0 0 0-8 4c0 7 8 12 8 12Z"/></svg>`};return icons[type]||icons.gift}
function detailImageList(p,selected=''){const base=[selected,...productImages(p)].filter(Boolean);return [...new Set(base)]}
function detailMediaHtml(p,src=''){const imgs=detailImageList(p,src);if(!imgs.length)return `<div class="visualFallback">${categoryIconSvg(p.productType||p.category)}</div>`;return `<div class="detailCarousel" id="detailCarousel"><div class="detailCarouselBadge">${imgs.length} ta rasm</div><div class="detailSlides" id="detailSlides">${imgs.map((u,i)=>`<div class="detailSlide" data-index="${i}"><img src="${esc(u)}" alt="${esc(p.name)} ${i+1}" loading="lazy"></div>`).join('')}</div>${imgs.length>1?`<button class="detailNavBtn prev" type="button" onclick="goDetailSlide(-1)"><svg viewBox="0 0 24 24"><path d="m15 18-6-6 6-6"/></svg></button><button class="detailNavBtn next" type="button" onclick="goDetailSlide(1)"><svg viewBox="0 0 24 24"><path d="m9 18 6-6-6-6"/></svg></button><div class="detailSlideDots" id="detailSlideDots">${imgs.map((_,i)=>`<button type="button" class="${i===0?'active':''}" onclick="goDetailSlide(${i},true)"></button>`).join('')}</div><div class="detailThumbRow">${imgs.map((u,i)=>`<button type="button" class="detailThumb ${i===0?'active':''}" data-thumb-index="${i}" onclick="goDetailSlide(${i},true)"><img src="${esc(u)}" alt="thumb ${i+1}" loading="lazy"></button>`).join('')}</div>`:''}</div>`}
function setDetailImage(src){const p=state.currentProduct;if(!$('detailHeroMedia')||!p)return;$('detailHeroMedia').innerHTML=detailMediaHtml(p,src);initDetailSlider();}
function initDetailSlider(){clearInterval(state.detailSlideTimer);const wrap=$('detailCarousel');const slides=$('detailSlides');if(!wrap||!slides)return;const total=slides.children.length||0;state.detailSlideIndex=Math.min(state.detailSlideIndex||0,Math.max(0,total-1));syncDetailSlides();if(total>1){state.detailSlideTimer=setInterval(()=>goDetailSlide(1),3200);let startX=0;wrap.addEventListener('touchstart',e=>{startX=e.touches[0].clientX;state.detailTouchStartX=startX;clearInterval(state.detailSlideTimer)},{passive:true});wrap.addEventListener('touchend',e=>{const endX=e.changedTouches[0].clientX;const diff=endX-(state.detailTouchStartX||startX);if(Math.abs(diff)>35)goDetailSlide(diff<0?1:-1);startDetailAuto();},{passive:true});}}
function startDetailAuto(){clearInterval(state.detailSlideTimer);const slides=$('detailSlides');if(slides&&slides.children.length>1)state.detailSlideTimer=setInterval(()=>goDetailSlide(1),3200)}
function syncDetailSlides(){const slides=$('detailSlides');if(!slides)return;const total=slides.children.length||0;if(!total)return;slides.style.transform=`translateX(-${state.detailSlideIndex*100}%)`;document.querySelectorAll('#detailSlideDots button').forEach((b,i)=>b.classList.toggle('active',i===state.detailSlideIndex));document.querySelectorAll('[data-thumb-index]').forEach((b,i)=>b.classList.toggle('active',i===state.detailSlideIndex));}
window.goDetailSlide=function(step,absolute=false){const slides=$('detailSlides');if(!slides)return;const total=slides.children.length||0;if(!total)return;if(absolute)state.detailSlideIndex=Math.max(0,Math.min(total-1,Number(step)||0));else state.detailSlideIndex=(state.detailSlideIndex+(Number(step)||0)+total)%total;syncDetailSlides();startDetailAuto();}
function variantPriceMin(p){const prices=(p.variants||[]).map(v=>Number(v.price||0)).filter(Boolean);return prices.length?Math.min(Number(p.price||0)||prices[0],...prices):Number(p.price||0)}
function detailVariantOptions(p){const vs=Array.isArray(p.variants)?p.variants:[];if(!vs.length)return `<div class="subpanel"><h3>${infoIconSvg('spark')} Tanlov tafsiloti</h3><div class="muted">Bu mahsulotda alohida rang/o‘lcham varianti kiritilmagan. Buyurtma izohida xohlagan rang, uslub va o‘lchamni yozib qoldirishingiz mumkin.</div><div class="detailHint">Agar bir nechta rasm yuklangan bo‘lsa, yuqoridagi slayder orqali qo‘l bilan surib ko‘rishingiz mumkin.</div><input id="detailVariant" type="hidden" value=""><input id="detailColor" type="hidden" value=""><input id="detailSize" type="hidden" value=""></div>`;return `<div class="subpanel variantPickPanel"><h3>${infoIconSvg('spark')} Rang va o‘lchamni tanlang</h3><input id="detailVariant" type="hidden" value="0"><input id="detailColor" type="hidden" value=""><input id="detailSize" type="hidden" value=""><div class="detailVariantGrid">${vs.map((v,i)=>`<button type="button" class="variantOption ${i===0?'active':''}" onclick="selectDetailVariant(${i})"><span class="variantThumb">${v.imageUrl?`<img src="${esc(v.imageUrl)}" alt="${esc(v.label)}" loading="lazy">`:categoryIconSvg(p.productType||p.category)}</span><span><b>${esc(v.label||['Variant',i+1].join(' '))}</b><small>${[v.color,v.size].filter(Boolean).map(esc).join(' · ')||'Maxsus tanlov'}</small><span class="variantSwatch"><i></i>${money(v.price||p.price)}${Number(v.stockQty||0)>0?` · ${Number(v.stockQty)} ta`:''}</span></span></button>`).join('')}</div><div id="variantInfo" class="muted" style="margin-top:7px"></div><div class="detailHint">Yuqoridagi asosiy rasm maydonida auto-slide ishlaydi. Xohlasangiz chap/o‘ng tugmalar yoki barmoq bilan surib ko‘rishingiz mumkin.</div></div>`}
window.selectDetailVariant=function(i){const p=state.currentProduct;if(!p)return;state.currentVariantIndex=Number(i)||0;if($('detailVariant'))$('detailVariant').value=String(state.currentVariantIndex);document.querySelectorAll('.variantOption').forEach((b,idx)=>b.classList.toggle('active',idx===state.currentVariantIndex));syncDetailVariant();}
window.syncDetailVariant=function(){const p=state.currentProduct;if(!p)return;const vs=Array.isArray(p.variants)?p.variants:[];const idx=Number($('detailVariant')?.value||0);const v=vs[idx];if(v){if($('detailColor'))$('detailColor').value=v.color||'';if($('detailSize'))$('detailSize').value=v.size||'';if($('detailPrice'))$('detailPrice').textContent=money(v.price||p.price);if($('detailOldPrice'))$('detailOldPrice').textContent=v.oldPrice?money(v.oldPrice):'';if($('variantInfo'))$('variantInfo').textContent=`Tanlangan: ${v.label||'variant'}${v.color?' · '+v.color:''}${v.size?' · '+v.size:''}${Number(v.stockQty||0)>0?' · omborda '+Number(v.stockQty)+' ta':''}`;setDetailImage(v.imageUrl||p.imageUrl||productImages(p)[0]||'');}else{if($('detailPrice'))$('detailPrice').textContent=money(p.price);if($('detailOldPrice'))$('detailOldPrice').textContent=p.oldPrice?money(p.oldPrice):'';if($('variantInfo'))$('variantInfo').textContent='Asosiy variant';setDetailImage(p.imageUrl||productImages(p)[0]||'');}}
async function renderDetailReviews(id){try{const d=await api(`/api/products/${id}/reviews`);const list=(d.reviews||[]).map(r=>`<div class="reviewBox"><div><b>${esc(r.fullName||'Mijoz')}</b> · ${'★'.repeat(Number(r.rating||0))}${'☆'.repeat(5-Number(r.rating||0))}</div>${r.comment?`<div style="margin-top:4px">${esc(r.comment)}</div>`:''}<div class="reviewMeta">${new Date(r.createdAt).toLocaleDateString('uz-UZ')}</div>${r.adminReply?`<div class="replyBox"><b>Admin javobi:</b><div>${esc(r.adminReply)}</div></div>`:''}</div>`).join('')||'<div class="empty">Hozircha fikr yo‘q.</div>';if($('detailReviewList'))$('detailReviewList').innerHTML=list;if($('detailReviewSummary'))$('detailReviewSummary').textContent=`O‘rtacha baho: ${d.avgRating} / 5 · ${d.reviewCount} ta fikr`; }catch(e){if($('detailReviewList'))$('detailReviewList').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
window.setRating=function(n){state.currentRating=n;document.querySelectorAll('.starBtn').forEach((b,i)=>b.classList.toggle('active',i<Number(n)))}
window.submitReview=async function(){if(!state.currentProduct)return;try{if(!state.currentRating)throw new Error('Bahoni tanlang');await api(`/api/products/${state.currentProduct._id}/reviews`,{method:'POST',body:JSON.stringify({rating:state.currentRating,comment:$('detailComment').value})});toast('Fikringiz saqlandi');$('detailComment').value='';setRating(0);await renderDetailReviews(state.currentProduct._id);await loadReviewSummary();renderProducts();}catch(e){toast(e.message)}}
window.addDetailToCart=function(mode='SCHEDULED'){const p=state.currentProduct;if(!p)return;const vs=Array.isArray(p.variants)?p.variants:[];const idx=Number($('detailVariant')?.value||0);const v=vs[idx];addToCart(p._id,{variantSku:v?.sku||'',variantLabel:v?.label||'',selectedColor:$('detailColor')?.value||v?.color||'',selectedSize:$('detailSize')?.value||v?.size||'',price:v?.price||p.price});if($('orderMode'))$('orderMode').value=mode;handleModeChange();showSection('cart');}
function detailTags(p){const tags=[...(p.occasionTags||[]),...(p.recipientTags||[]),...(p.colorOptions||[]).slice(0,3),(p.minLeadDays||0)+' kun oldin'].filter(Boolean);return tags.length?`<div class="detailTags">${tags.slice(0,10).map(t=>`<span class="detailTag">${esc(t)}</span>`).join('')}</div>`:''}
window.openProduct=async function(id){try{const d=await api(`/api/products/${id}`);const p=d.product;state.currentProduct=p;state.currentVariantIndex=0;state.detailSlideIndex=0;const basePrice=variantPriceMin(p);$('detailWrap').classList.add('detailShell');$('detailWrap').innerHTML=`<div class="pageHead"><div><h2>Batafsil sahifa</h2><small>${esc(p.category)} · ${p.minLeadDays||0} kun oldin buyurtma</small></div><button class="ghost mini" onclick="showSection('${p.productType==='SERVICE'?'servicesPage':'catalog'}')">Ortga</button></div><div class="detailHero"><div id="detailHeroMedia" class="detailHeroMedia">${detailMediaHtml(p)}</div><div class="detailHeroBody"><div class="detailTitleRow"><div><h2>${esc(p.name)}</h2><div class="muted">${esc(p.shortDescription||p.description||'Bayram va tug‘ilgan kunlar uchun mos sovg‘a')}</div></div><span class="badge" style="position:static">${isExpressProduct(p)?'Tezkor':'Premium'}</span></div><div class="detailPriceBlock"><div><div id="detailPrice" class="detailPrice">${money(basePrice)}</div><div id="detailOldPrice" class="old">${p.oldPrice?money(p.oldPrice):''}</div></div><button class="btn" onclick="addDetailToCart('${isExpressProduct(p)?'EXPRESS_RANDOM':'SCHEDULED'}')">Savatga qo‘shish</button></div>${detailTags(p)}</div></div><div class="trustGrid"><div class="trustCard">${infoIconSvg('gift')}<b>Bayramga mos</b><span>tug‘ilgan kun, sevgi, to‘y</span></div><div class="trustCard">${infoIconSvg('spark')}<b>Variantli narx</b><span>rang va o‘lchamga qarab</span></div><div class="trustCard">${infoIconSvg('truck')}<b>Rejali yetkazish</b><span>oldindan nazorat</span></div></div>${detailVariantOptions(p)}<div class="detailInfoGrid"><div class="detailInfo"><h3>${infoIconSvg('gift')} Tavsif</h3><p class="muted">${esc(p.description||p.shortDescription||'')}</p>${p.packageIncludes?`<p class="muted"><b>Ichida:</b> ${esc(p.packageIncludes)}</p>`:''}${p.composition?`<p class="muted"><b>Tarkibi:</b> ${esc(p.composition)}</p>`:''}</div><div class="detailInfo"><h3>${infoIconSvg('care')} Tayyorlash va parvarish</h3>${p.preparationNote?`<p class="muted"><b>Tayyorlash:</b> ${esc(p.preparationNote)}</p>`:''}${p.careInstructions?`<p class="muted"><b>Saqlash:</b> ${esc(p.careInstructions)}</p>`:''}${p.deliveryNotes?`<p class="muted"><b>Yetkazish:</b> ${esc(p.deliveryNotes)}</p>`:''}</div></div><div class="subpanel"><h3>${infoIconSvg('spark')} Baholash va fikr</h3><div id="detailReviewSummary" class="muted">Yuklanmoqda...</div><div class="stars">${[1,2,3,4,5].map(n=>`<button class="starBtn" type="button" onclick="setRating(${n})">★</button>`).join('')}</div><div class="field"><label>Izoh</label><textarea id="detailComment" placeholder="Ixtiyoriy izoh"></textarea></div><button class="ghost" onclick="submitReview()">Fikr yuborish</button><div id="detailReviewList"></div></div><div class="detailActionBar"><button class="ghost" onclick="showSection('${p.productType==='SERVICE'?'servicesPage':'catalog'}')">Ortga</button><button class="btn" onclick="addDetailToCart('${isExpressProduct(p)?'EXPRESS_RANDOM':'SCHEDULED'}')">Savatga qo‘shish</button></div>`;showSection('detail');initDetailSlider();syncDetailVariant();await renderDetailReviews(id);}catch(e){toast(e.message)}}
function cleanBusinessText(){const s=state.settings||{};const address=esc(s.businessAddress||s.restaurantAddress||'Manzil kiritilmagan');const phone=esc(s.businessPhone||s.restaurantPhone||'+998');const hours=esc(s.openingHours||'Ish vaqti ko‘rsatilmagan');const insta=esc(s.instagram||'—');const el=$('businessInfo');if(el)el.innerHTML=`<div class="bizGrid"><div class="bizCard"><span class="bizIcon"><svg viewBox="0 0 24 24"><path d="M12 21s-6-5.3-6-11a6 6 0 1 1 12 0c0 5.7-6 11-6 11Z"/><circle cx="12" cy="10" r="2.5"/></svg></span><b>Manzil</b><div class="muted">${address}</div></div><div class="bizCard"><span class="bizIcon"><svg viewBox="0 0 24 24"><path d="M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7l.4 2.6a2 2 0 0 1-.6 1.8L7.2 9.8a16 16 0 0 0 7 7l1.7-1.7a2 2 0 0 1 1.8-.6l2.6.4A2 2 0 0 1 22 16.9Z"/></svg></span><b>Aloqa</b><div class="muted">${phone}</div></div><div class="bizCard"><span class="bizIcon"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 3"/></svg></span><b>Ish vaqti</b><div class="muted">${hours}</div></div><div class="bizCard"><span class="bizIcon"><svg viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><path d="M17.5 6.5h.01"/></svg></span><b>Instagram</b><div class="muted">${insta}</div></div></div>`;}


  boot();
  setTimeout(async()=>{cleanBusinessText();await loadReviewSummary();renderProducts();},600);
})();